contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough ether for deposit");

        // set up a nonzero balance for this contract in c
        c.deposit{value: depositAmount}();

        uint256 beforeBalance = c.balances(address(this));
        uint256 beforeContractEther = address(this).balance;

        // decide on an amount that is valid with respect to the observable balance
        uint256 amount = withdrawAmount % (beforeBalance + 1);
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balances(address(this));

        assert(
            !reverted
                ? (afterBalance + amount == beforeBalance && address(this).balance == beforeContractEther + amount)
                : (afterBalance == beforeBalance && address(this).balance == beforeContractEther)
        );
    }

    receive() external payable {}
}

