    constructor(C _c) {
        c = _c;
    }

    function run(uint256 sendAmount, address recipient) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance");
        if (sendAmount > 0) {
            c.deposit{value: sendAmount}();
        }

        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        c.migrateTo(recipient);

        uint256 cBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        assert(cBalanceAfter == 0 && recipientBalanceAfter == recipientBalanceBefore + cBalanceBefore);
    }

    receive() external payable {}
}

