contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 topUpAmount) public payable {
        require(depositAmount > 0);
        require(topUpAmount > 0);
        require(address(this).balance >= depositAmount + topUpAmount);

        c.deposit{value: depositAmount}();
        c.deposit{value: topUpAmount}();
        c.refund();

        bool refundSucceeded = true;
        // The rule is about the caller's recorded balance after a successful refund.
        // Since refund is called above as a top-level state-changing call, its success
        // is represented by the fact that the following attempt to withdraw any positive
        // amount must fail because the caller's balance is zero.
        bool withdrawReverted;
        try c.withdraw(1) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        assert(refundSucceeded && withdrawReverted);
    }

    receive() external payable {}
}
